# UTF-8 一键启动：后端 + 前端
$ErrorActionPreference = "Stop"
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location -LiteralPath $Root

# 检查 Node.js
$nodeCmd = Get-Command node -ErrorAction SilentlyContinue
if (-not $nodeCmd) {
    Write-Host "未检测到 Node.js，请先安装：https://nodejs.org/" -ForegroundColor Red
    exit 1
}

# 依赖安装
if (-not (Test-Path -LiteralPath (Join-Path $Root "node_modules"))) {
    Write-Host "首次运行，正在安装依赖…" -ForegroundColor Yellow
    npm install
    if ($LASTEXITCODE -ne 0) {
        Write-Host "npm install 失败，请检查网络或 Node 版本。" -ForegroundColor Red
        exit 1
    }
}

# 日志目录
$logsDir = Join-Path $Root "logs"
if (-not (Test-Path -LiteralPath $logsDir)) {
    New-Item -ItemType Directory -Path $logsDir -Force | Out-Null
}

$serverLog = Join-Path $logsDir "server.log"
$devLog = Join-Path $logsDir "dev.log"

Write-Host "正在启动后端与前端（日志：logs/）…" -ForegroundColor Cyan

# 通过 cmd 启动，避免 PowerShell 引号/路径问题
Start-Process -FilePath "cmd.exe" `
    -ArgumentList "/c", "npm run server >> `"$serverLog`" 2>&1" `
    -WorkingDirectory $Root `
    -WindowStyle Minimized

Start-Process -FilePath "cmd.exe" `
    -ArgumentList "/c", "npm run dev >> `"$devLog`" 2>&1" `
    -WorkingDirectory $Root `
    -WindowStyle Minimized

function Test-EndpointReady {
    param([string]$Url)
    try {
        $resp = Invoke-WebRequest -Uri $Url -UseBasicParsing -TimeoutSec 2 -ErrorAction Stop
        return ($resp.StatusCode -ge 200 -and $resp.StatusCode -lt 400)
    } catch {
        return $false
    }
}

$backendUrl = "http://127.0.0.1:8787/api/health"
$frontendUrl = "http://127.0.0.1:5173/"
$deadline = (Get-Date).AddSeconds(60)
$backendReady = $false
$frontendReady = $false

Write-Host "等待服务就绪（最多 60 秒）…" -ForegroundColor Yellow

while ((Get-Date) -lt $deadline) {
    if (-not $backendReady) {
        $backendReady = Test-EndpointReady -Url $backendUrl
    }
    if (-not $frontendReady) {
        $frontendReady = Test-EndpointReady -Url $frontendUrl
    }
    if ($backendReady -and $frontendReady) {
        break
    }
    Start-Sleep -Seconds 1
}

if ($backendReady -and $frontendReady) {
    Write-Host "服务已就绪，正在打开应用…" -ForegroundColor Green
    Start-Process $frontendUrl
    exit 0
}

Write-Host "服务尚未完全就绪。" -ForegroundColor Yellow
if (-not $backendReady) {
    Write-Host "  后端未响应：$backendUrl" -ForegroundColor Yellow
}
if (-not $frontendReady) {
    Write-Host "  前端未响应：$frontendUrl" -ForegroundColor Yellow
}
Write-Host "已打开体验入口页；请查看 logs/server.log 与 logs/dev.log。" -ForegroundColor Yellow

$entryHtml = Join-Path $Root "experience-entry.html"
if (Test-Path -LiteralPath $entryHtml) {
    Start-Process $entryHtml
} else {
    $entryHtmlZh = Join-Path $Root "体验入口.html"
    if (Test-Path -LiteralPath $entryHtmlZh) {
        Start-Process $entryHtmlZh
    }
}

exit 1

